import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static int n, m, mod;
    static int[][] C = new int[MAXN][MAXN];
    static Pair[][] dp = new Pair[MAXN][MAXN];

    static class Pair {
        int f, s;

        Pair(int f, int s) {
            this.f = f;
            this.s = s;
        }

        Pair add(Pair b) {
            return new Pair(addMod(this.f, b.f), addMod(this.s, b.s));
        }

        Pair multiply(Pair b) {
            long fi = ((long) this.f * b.f) % mod;
            long se = ((long) this.f * b.s + (long) this.s * b.f) % mod;
            return new Pair((int) fi, (int) se);
        }
    }

    static int sumRange(int l, int r) {
        return (l + r) * (r - l + 1) / 2;
    }

    static int addMod(int a, int b) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = addMod(C[i - 1][j], C[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Pair(0, 0);
            }
        }

        for (int i = 0; i <= n; i++) {
            dp[i][0] = new Pair(1, 0);
            for (int j = 1; j <= i && j <= m; j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        Pair term = dp[k - 1][k - 1].multiply(dp[i - k][j - k + 1]).multiply(new Pair(C[j][k - 1], 0));
                        dp[i][j] = dp[i][j].add(term);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        Pair t1 = dp[k - 1][k - 1];
                        Pair t2 = dp[i - k][i - k];
                        Pair combi = new Pair(C[i - 1][k - 1], 0);
                        int fct = i + 1 - sumRange(1, k) + sumRange(k + 1, i) - k * (i - k);
                        Pair fctp = new Pair(fct, 0);
                        Pair term = t1.multiply(t2).multiply(combi).multiply(fctp);
                        dp[i][j] = dp[i][j].add(term);
                    }
                }
            }
        }
        System.out.println(dp[n][m].s);
        sc.close();
    }
}
